app.controller('SearchJob', ['$rootScope', '$scope', '$http', 'commonEnum', function ($rootScope, $scope, $http, commonEnum) {
    var pageUrl = "../Services/SearchJobsService.asmx";
    var autoCompleteUrl = "../Services/wsAutoComplete.asmx";

    var jobsPerPage = 10;
    /*For any Client specific jobs count, define variable and assign required value into _customSearchJobsPerPage
      Ex, var _customSearchJobsPerPage=50;
     * */
    var custSearchJobsPerPage = window["_customSearchJobsPerPage"];
    if (custSearchJobsPerPage != null && typeof custSearchJobsPerPage != "undefined") {
        jobsPerPage = parseInt(custSearchJobsPerPage);
    }

    var filterDataSourceTemp = window["filterDataSource"];
    if (filterDataSourceTemp == null || typeof filterDataSourceTemp == "undefined") {
        filterDataSourceTemp = null;
    }


    $scope.jobSuggestions = {};
    $scope.jobs = {};
    $scope.footerData = null;
    $scope.autoSuggestList = false;
    $scope.jobsPerPage = jobsPerPage;
    $scope.jobsFrom = 1;
    $scope.jobsTo = $scope.jobsFrom + $scope.jobsPerPage;
    $scope.jobsInfo = {
        intFunctionalArea: 0,
        intPageIndex: 1,
        searchKeyword: '',
        strLocation: '',
        jobSearch: '',
        queryString: '',
        FilterDataSource: filterDataSourceTemp
    }

    var queryString = window.location.search;
    if (queryString.length > 0 && queryString.indexOf('-jobs') > 0)
        $scope.jobsInfo.jobSearch = queryString.substr(1, queryString.indexOf('-jobs') - 1);

    if (queryString.length > 0 && queryString.indexOf('JB_') > 0)
        $scope.jobsInfo.queryString = decodeURI(queryString.substr(1, queryString.length));

    $scope.clearList = function () {
        //$scope.jobsInfo.searchKeyword = null;
        $scope.autoSuggestList = false;
    }

    $scope.selectedItem = function (keyword) {
        $scope.jobsInfo.searchKeyword = keyword;
        $scope.autoSuggestList = false;
    }

    $scope.getKeywords = function (keyword) {
        $http.post(autoCompleteUrl + "/GetKeywords", '{"prefixText":"' + keyword + '","count":' + 5 + '}')
            .success(function (response) {
                $scope.keywords = response.d;
                $scope.autoSuggestList = true;
            })
    }

    $scope.getHotLinksAndJobs = function () {
        StartLoader();
        $scope.renderComplete = false;
        $http.post(pageUrl + "/GetHotLinksAndJobs", '{"parameters":\'' + JSON.stringify($scope.jobsInfo) + '\'}')
            .success(function (response) {
                if (response.d != '') {
                    var data = JSON.parse(response.d);
                    $scope.jobSuggestions = data.JobSuggestion;
                    $scope.jobs = data.Jobs;
                    $scope.pageChange();
                }
                else {
                    $scope.jobSuggestions = {};
                    $scope.jobs = {};
                }

            })
            .error(function (error) {
                console.log(error);
            })
            .finally(function () {
                StopLoader();
            });
    }

    $scope.getFooterData = function () {

        $http.post(pageUrl + "/GetFunctionLocationIndustry", '{"menuIds":"3,12,86"}')
            .success(function (response) {
                if (response.d != '') {
                    var data = JSON.parse(response.d);
                    $scope.footerData = data.FooterData;
                }
                else {
                    $scope.footerData = null;
                }
            })
            .error(function (error) {
                console.log(error);
            })
            .finally(function () {
                //StopLoader();
            });
    }

    $scope.templateUrl = function () {
        return GetTemplateUrl();//'/AngularVersion/Templates/Search_Default.html';
    }

    $scope.searchJob = function () {
        $scope.jobsInfo.intPageIndex = 1;
        $scope.getHotLinksAndJobs();
    }

    $scope.browseAllJobs = function () {

        $scope.jobsInfo.intPageIndex = 1;
        $scope.jobsInfo.searchKeyword = '';
        $scope.jobsInfo.jobSearch = '';
        $scope.getHotLinksAndJobs();
    }

    $scope.pageChange = function () {
        $scope.jobsFrom = ($scope.jobsPerPage * ($scope.jobsInfo.intPageIndex - 1)) + 1;
        $scope.jobsTo = $scope.jobsPerPage * $scope.jobsInfo.intPageIndex;
        if ($scope.jobsTo > $scope.jobs.length)
            $scope.jobsTo = $scope.jobs.length;
    }

    $scope.ConvertTickToDate = function (str) {
        return tickFormat(str);
    }

    $scope.getFooterData();
    $scope.getHotLinksAndJobs();
}]);

app.directive('myEnter', function () {
    return function (scope, element, attrs) {
        element.bind("keydown keypress", function (event) {
            if (event.which === 13) {
                scope.$apply(function () {
                    scope.$eval(attrs.myEnter);
                });

                event.preventDefault();
            }
        });
    };
});

