function parseJson(data) {
    data = data.replace('\n', '', 'g');

    var
        start = data.indexOf('{'),
        open = 0,
        i = start,
        len = data.length,
        result = [];

    for (; i < len; i++) {
        if (data[i] == '{') {
            open++;
        } else if (data[i] == '}') {
            open--;
            if (open === 0) {
                result.push(JSON.parse(data.substring(start, i + 1)));
                start = i + 1;
            }
        }
    }
    return result;
}

