function DataArrayofObject(data, withSpace) {
    withSpace = typeof withSpace !== 'undefined' ? withSpace : false;
    var keys = data.shift(),
        i = 0, k = 0,
        obj = null,
        output = [];

    for (i = 0; i < data.length; i++) {
        obj = {};

        for (k = 0; k < keys.length; k++) {
            if (withSpace) {
                obj[keys[k]] = data[i][k];
            }
            else {
                obj[keys[k].replace(/ /g, '_').replace('/', '_')] = data[i][k];
            }
        }
        output.push(obj);
    }

    return ($.map(output, function (el) { return el }));
}


