function GetQueryString(name, url) {
    if (!url) {
        url = window.location.href;
    }

    if (name != "enc") {
        url = url.search("enc") > 0 ? DecryptUrl(url) : url;
    }

    name = name.replace(/[\[\]]/g, '\\$&');
    var regex = new RegExp('[?&]' + name + '(=([^&#]*)|&|#|$)'),
        results = regex.exec(url);

    if (!results)
        return null;
    if (!results[2])
        return '';

    return decodeURIComponent(results[2].replace(/\+/g, ' '));
}



function Pager(ulPager, PageIndex, TotalRecords, DisplayRecords) {
    try {
        var PageCount = parseInt(Math.ceil((parseFloat(TotalRecords) / parseFloat(DisplayRecords))));
        var jsonArr = [];
        var startIndex = 0;
        var lastIndex = 9;
        if (PageIndex > 6) {
            startIndex = PageIndex - 6;
            lastIndex = startIndex + 9;
        }
        if (lastIndex >= PageCount) {
            lastIndex = PageCount - 1;
        }
        if (PageCount > 1) {
            for (var i = startIndex; i <= lastIndex; i++) {
                jsonArr.push({ Id: i + 1 });
            }
            document.getElementById(ulPager).style.display = "inline-flex";
            if (PageIndex > 1) {
                document.getElementById(ulPager).getElementsByTagName('li')[0].style.display = "block";
            }
            else {
                document.getElementById(ulPager).getElementsByTagName('li')[0].style.display = "none";
            }
            var liLength = document.getElementById(ulPager).getElementsByTagName('li').length;
            if (PageIndex < PageCount) {
                document.getElementById(ulPager).getElementsByTagName('li')[liLength - 1].style.display = "block";
            }
            else {
                document.getElementById(ulPager).getElementsByTagName('li')[liLength - 1].style.display = "none";
            }
        }
        else {
            document.getElementById(ulPager).style.display = "none";
        }
    } catch (e) {
        alert(e);
    }
    return jsonArr;
}
function FindChild(dataSource, IsChecked) {
    var parentItems = [];
    dataSource.forEach(function (item, index) {
        if (item.PARENT_ID == 0) {
            parentItems.push({
                VALUE_ID: item.VALUE_ID,
                VALUE_NAME: item.VALUE_NAME,
                IS_CHECKED: (item.IS_CHECKED == undefined) ? IsChecked : item.IS_CHECKED
            });
        }
        else if (item.PARENT_ID == undefined) {
            parentItems.push({
                VALUE_ID: 0, //Object does not support in IE
                VALUE_NAME: 'Any',
                IS_CHECKED: (item.IS_CHECKED == undefined) ? IsChecked : item.IS_CHECKED
            });
        }
    });
    parentItems.forEach(function (item, index) {
        //if (item.PARENT_ID != undefined)
        item.datasource = BindItem(dataSource, item, IsChecked);
    });
    return parentItems;
};
function BindItem(dataSource, parentItem, IsChecked) {
    var childItems = [];
    dataSource.forEach(function (eachItem, index) {
        if (eachItem.PARENT_ID != undefined) {
            if (eachItem.PARENT_ID == parentItem.VALUE_ID && parentItem.VALUE_ID != 0) {
                childItems.push({
                    VALUE_ID: eachItem.VALUE_ID,
                    VALUE_NAME: eachItem.VALUE_NAME,
                    IS_CHECKED: (eachItem.IS_CHECKED == undefined) ? IsChecked : eachItem.IS_CHECKED,
                    datasource: BindItem(dataSource, eachItem, IsChecked)
                });

            }
        }
    });
    return childItems;
};

