    if (cblId != null) {
        if (ctrlType) {
            selecteditems += "[" + cblId[2].value + "," + (cblId[2].checked ? 1 : 0) + '],';
        }
        for (i = 1; i < cblId.length; i++) {
            if (cblId[i].checked && !isNaN(parseInt(cblId[i].value))) {
                if (i != 1) {
                    if (ctrlType) {
