function ResetSkillLangData(SkillId, LanguageId) {
    ClearElementData(document.getElementById(SkillId));
    ClearElementData(document.getElementById(LanguageId));
}

function ClearElementData(divElement) {
    try {
        var ele = divElement.querySelectorAll("input, select, checkbox");
        for (i = 0; i < ele.length; i++) {
            var child = ele[i];
            if (child) {
                switch (child.type) {
                    case 'text':
                        child.value = '';
                        break;
                    case 'select-one':
                        child.value = child.options[0].value;
                        break;
                    case 'checkbox':
                    case 'radio':
                        child.checked = false;
                        break;
                }
            }
        }
    }
    catch (ex) {
        console.log(ex);
    }
}

