function draggableHeader(className, tableHeaders, headersToHide, conditionalheadersToHide, condition) {
    var draggableHeader = [];
    var tempHeader = [];
    var localStorageSequence = getLocalStorageItem(className);
    if ((localStorageSequence != null) && (localStorageSequence.length > 9)) {
        draggableHeader = compareHeaders(getDefaultHeaderSequence(tableHeaders, headersToHide), JSON.parse(getLocalStorageItem(className)));

        if (conditionalheadersToHide != undefined) {
            draggableHeader = conditionalHeadersToHide(draggableHeader, conditionalheadersToHide, condition);
        }

        localStorage.setItem(className, JSON.stringify(draggableHeader));

        for (var i = 0; i < draggableHeader.length; i++) {
            var object = {};
            object[0] = draggableHeader[i][0];
            object[1] = draggableHeader[i][1];
            object[2] = draggableHeader[i][2];
            tempHeader.push(object);
        }
        return tempHeader;
    }
    else {
        return setHeaderSequenceFromDb(className, tableHeaders, headersToHide, conditionalheadersToHide, condition);
    }
}

function getDefaultHeaderSequence(tableHeaders, headersToHide) {
    var tempHeader = []; //tempHeaderArray
    var defaultHeaderSequence = [];

    for (var i = 0; i < tableHeaders.length; i++) {
        tempHeader.push(tableHeaders[i][0]);
    }

    $.grep(tempHeader, function (x) {
        if (!headersToHide.includes(x)) {
            defaultHeaderSequence.push([tempHeader[tempHeader.indexOf(x)], ResourceManager.GetResourceText(tempHeader[tempHeader.indexOf(x)]), true]);
        }
    });
    return defaultHeaderSequence;
}

function conditionalHeadersToHide(tableHeaders, conditionalheadersToHide, condition) {
    if (condition) {
        var tempHeader = [];
        var defaultHeaderSequence = [];

        for (var i = 0; i < tableHeaders.length; i++) {
            tempHeader.push(tableHeaders[i][0]);
        }

        $.grep(tempHeader, function (x) {
            var flag = true;
            if (!conditionalheadersToHide.includes(x)) {
                tableHeaders.forEach(function (y) {
                    if (y[0] == x)
                        flag = y[2];
                });
                defaultHeaderSequence.push([tempHeader[tempHeader.indexOf(x)], ResourceManager.GetResourceText(tempHeader[tempHeader.indexOf(x)]), flag]);
            }
        });

        return defaultHeaderSequence;
    }
    else
        return tableHeaders;
}

