function setHeaderSequenceFromDb(className, tableHeaders, headersToHide, conditionalheadersToHide, condition) {
    var tempHeader = [];
    var url = window.location.origin + "/OnlineUserHandler.asmx/GetUserCustomColumn";

    $.ajax({
        async: false,
        method: "POST",
        url: url,
        data: '{clsName:"' + className + '"}',
        contentType: "application/json; charset=utf-8",
        dataType: "json",
        success: function (response) {
            if (response != null && response.d != '') {
                tempHeader = JSON.parse(response.d);
            }
            else {
                console.log("Setting default sequence..");
                tempHeader = getDefaultHeaderSequence(tableHeaders, headersToHide);
            }
        },
        error: function (response) {
            console.log(response);
        },
        complete: function () {
            tempHeader = compareHeaders(getDefaultHeaderSequence(tableHeaders, headersToHide), tempHeader);

            if (conditionalheadersToHide != undefined) {
                tempHeader = conditionalHeadersToHide(tempHeader, conditionalheadersToHide, condition);
            }

            localStorage.setItem(className, JSON.stringify(tempHeader));
            console.log("finished loading custom headers.");
        }
    });
    return tempHeader;
}

function compareHeaders(x, y) {
    var a = [], b = [], c = [], d = [], e = [], diff = [];
    a = x;
    if (y != undefined) {
        b = y.slice();
    }

    a.forEach(function (e, i) {
        c.push(a[i][0]);
    });

    b.forEach(function (e, i) {
        d.push(b[i][0]);
    });

    c.forEach(function (i) {
        if (!d.includes(i)) {
            diff.push(i);
        }
    });

    d.forEach(function (i) {
        if (!c.includes(i)) {
            diff.push(i);
        }
    });

    diff.forEach(function (i) {
        if (c.includes(i) && !d.includes(i)) {
            d.push(i);
        }
        else {
            d.splice(d.indexOf(i), 1);
        }
    });

    d.forEach(function (i) {
        var flag = true;
        b.forEach(function (x) {
            if (x[0] == i && x[2] != (undefined || null))
                flag = x[2];
        })
        e.push([i, ResourceManager.GetResourceText(i), flag]);
    });

    return e;
}


function updateHeaderSequence(collection, extendedClassName) {
