    $.ajax({
        type: "POST",
        url: url,
        async: false,
        data: "{column:'" + JSON.stringify(collection) + "',clsName: '" + className + "'}",
        contentType: "application/json; charset=utf-8",
        dataType: "json",
        success: function (data, status) {
            //console.log(data,status);
        },
        error: function (error) {
            //console.log(error.status);
        }
    });
    localStorage.setItem(className, JSON.stringify(collection));
}
